Python, dict-based transition table, plus history.

```python
from enum import Enum


class OrderState(Enum):
    CREATED = "created"
    PAID = "paid"
    SHIPPED = "shipped"
    DELIVERED = "delivered"
    CANCELLED = "cancelled"
    REFUNDED = "refunded"


TRANSITIONS = {
    OrderState.CREATED:   {OrderState.PAID, OrderState.CANCELLED},
    OrderState.PAID:      {OrderState.SHIPPED, OrderState.REFUNDED},
    OrderState.SHIPPED:   {OrderState.DELIVERED},
    OrderState.DELIVERED: {OrderState.REFUNDED},
    OrderState.CANCELLED: set(),  # terminal
    OrderState.REFUNDED:  set(),  # terminal
}


class InvalidTransition(Exception):
    pass


class Order:
    def __init__(self, order_id):
        self.id = order_id
        self.state = OrderState.CREATED
        self.history = [OrderState.CREATED]

    def transition(self, new_state: OrderState):
        if new_state not in TRANSITIONS[self.state]:
            raise InvalidTransition(
                f"order {self.id}: {self.state.value} -> {new_state.value} not allowed"
            )
        self.state = new_state
        self.history.append(new_state)

    def pay(self):     self.transition(OrderState.PAID)
    def ship(self):    self.transition(OrderState.SHIPPED)
    def deliver(self): self.transition(OrderState.DELIVERED)
    def cancel(self):  self.transition(OrderState.CANCELLED)
    def refund(self):  self.transition(OrderState.REFUNDED)


if __name__ == "__main__":
    o = Order(1)
    o.pay(); o.ship(); o.deliver(); o.refund()
    print([s.value for s in o.history])  # created, paid, shipped, delivered, refunded

    o2 = Order(2)
    o2.cancel()
    try:
        o2.pay()
    except InvalidTransition as e:
        print(e)  # order 2: cancelled -> paid not allowed
```

Policy choices: cancel only before payment. A paid order goes to `refunded` because money must be returned. Shipped orders can't be cancelled or refunded until delivered. To change the rules, edit `TRANSITIONS` only.
Skipped: thread safety and persistence. Add a lock, or a DB `UPDATE ... WHERE state = <expected>`, when concurrent writers exist.
